<script setup lang="ts">
import { computed } from 'vue'
import type { CrmPlaybook, CrmRelation } from '../../../services/personalWorkApi'
const props = defineProps<{ playbook: CrmPlaybook | null; relations: CrmRelation[] }>()
const emit = defineEmits<{ navigate: [tab: 'workflow' | 'battle' | 'relation'] }>()
const followups = computed(() => props.playbook?.followups || [])
const overdue = computed(() => followups.value.filter(item => item.overdue).length)
const planned = computed(() => followups.value.filter(item => !item.overdue).length)
const recent = computed(() => [
  ...followups.value.slice(0, 3).map(item => ({ type: item.overdue ? '风险' : '跟进', text: item.next_step || '已登记下一步行动', time: item.due_date || '待定' })),
  ...props.relations.filter(item => item.decay_state !== 'normal').slice(0, 2).map(item => ({ type: '关系', text: `${item.person_name || '客户联系人'}需要维系`, time: item.days_since_touch == null ? '未触达' : `${item.days_since_touch}天` })),
].slice(0, 4))
</script>
<template><section class="action-center"><div class="action-center__stats"><button><small>今日待办</small><b>{{ followups.length }}</b></button><button class="warn"><small>逾期待办</small><b>{{ overdue }}</b></button><button><small>本周计划</small><b>{{ planned }}</b></button><button><small>需协调</small><b>0</b></button></div><div class="action-center__head"><strong>最近动态</strong><button @click="emit('navigate','workflow')">全部待办 →</button></div><div v-if="recent.length" class="action-center__timeline"><article v-for="(item,index) in recent" :key="index" :class="item.type"><i></i><span><em>{{ item.type }}</em>{{ item.text }}</span><time>{{ item.time }}</time></article></div><div v-else class="action-center__empty"><b>暂无待跟进行动</b><span>可在“关系维系”登记下一步与日期。</span></div><footer><button @click="emit('navigate','battle')">项目作战地图</button><button @click="emit('navigate','relation')">关系维系</button></footer></section></template>
